UPDATE civic_questions
SET prompt_ar = CASE question_key
        WHEN 'targeted-subsidies' THEN 'الدعم ديال الدولة خاصو يمشي بالدرجة اللولة للعائلات اللي محتاجاه، حتى إلا نقص الدعم العام ديال الأثمنة.'
        WHEN 'income-catch-up' THEN 'خاص السميگ ومعاشات التقاعد يطلعو مع الغلا، حتى إلا هادشي غادي يزيد فالمصاريف ديال الشركات والدولة.'
        WHEN 'essential-tax-relief' THEN 'خاصنا ننقصو الضرائب على الحوايج والخدمات الضرورية، حتى إلا نقصات الفلوس اللي كتمول بها الدولة خدمات أخرى.'
        WHEN 'competition-prices' THEN 'الأولوية خاصها تكون لمنافسة صحيحة ووضوح فالأرباح والأسواق، ماشي الدولة تبقى ديما كتحدد الأثمنة.'
        WHEN 'sme-jobs' THEN 'باش نخلقو فرص الشغل، خاصنا نسهلو على المقاولات الصغيرة والمتوسطة تكبر، ماشي نعتمدو بالأساس على التوظيف فالقطاع العام.'
        WHEN 'youth-apprenticeships' THEN 'التكوين من بعد المدرسة خاصو يكون مربوط أكثر بالتدريب فالمقاولات وبالخدمة اللي كاينة فالسوق.'
        WHEN 'women-work' THEN 'خاص الاستثمار فالحضانات والنقل الآمن والحماية فالخدمة يكون من الأولويات، باش نسهل على النساء يخدمو.'
        WHEN 'learning-accountability' THEN 'قبل ما نبنيو مدارس ومؤسسات جداد، خاصنا نعرفو واش التلاميذ كيتعلمو مزيان ونحاسبو المسؤولين على النتائج فالمدارس اللي كاينة.'
        WHEN 'preschool-dropout' THEN 'خاص التعليم الأولي ومحاربة الانقطاع عن القراية فالقرى ياخدو الأولوية قبل ما نوسعو الجامعات.'
        WHEN 'primary-care' THEN 'ميزانية الصحة خاصها تمشي اللول للمراكز القريبة وللأطباء والممرضين فالمناطق اللي ناقصين، قبل ما نبنيو مستشفيات كبار جداد.'
        WHEN 'medicine-financing' THEN 'خاص الدولة تفاوض باش تنقص أثمنة الدوا وتزيد فالتمويل ديال العلاج، حتى إلا هادشي غادي يحتاج مساهمات أو ضرائب أكثر.'
        WHEN 'water-allocation' THEN 'فوقت الجفاف، الما ديال الشرب والطبيعة خاصهم يجيو قبل الزراعات اللي كتاكل الما بزاف.'
        WHEN 'water-demand' THEN 'قبل ما نعتمدو بزاف على تحلية ونقل الما، خاصنا نوفروا فيه ونبدلو الزراعات اللي كتاكلو بزاف.'
        WHEN 'universal-protection' THEN 'خاص كلشي يكون عندو حد أدنى من الحماية الاجتماعية، حتى إلا هادشي غادي يحتاج ضرائب أو مساهمات أكثر.'
        WHEN 'public-transparency' THEN 'خاص صفقات الدولة وتصريحات المسؤولين على الممتلكات والمصالح يكونو واضحين ومتاحين للناس، حتى إلا ولات شي قرارات كتاخد وقت أكثر.'
        WHEN 'regional-powers' THEN 'خاص الجهات والجماعات ياخدو صلاحيات وميزانيات أكثر، وفنفس الوقت يتحاسبو بوضوح على النتائج.'
        WHEN 'connected-territories' THEN 'خاص الاستثمار فالنقل والسكن والخدمات فالمدن الصغيرة والقرى يجي قبل المشاريع الكبرى اللي متمركزة فالمدن الكبار.'
        WHEN 'equality-care' THEN 'خاص المساواة فالخدمة والدخل وتقاسم مسؤولية العناية بالدار والولاد يكونو من الأولويات، حتى إلا هادشي احتاج قوانين جديدة وميزانية أكثر.'
        ELSE prompt_ar
    END,
    context_ar = CASE question_key
        WHEN 'targeted-subsidies' THEN 'ملي كيتوجه الدعم، العائلات الهشة تقدر تستافد أكثر. ولكن إلا ما كانتش المعايير مضبوطة، شي ناس محتاجين يقدرو يبقاو برا.'
        WHEN 'income-catch-up' THEN 'هاد الزيادة غادي تحمي القدرة الشرائية، ولكن إلا كانت سريعة بزاف تقدر تأثر على فرص الشغل ومصاريف الدولة.'
        WHEN 'essential-tax-relief' THEN 'نقص الضريبة يقدر يهبط الثمن إلا وصل التخفيض للمستهلك. ولكن خاص المراقبة، وخاص الدولة تلقى منين تعوض المداخيل اللي نقصات.'
        WHEN 'competition-prices' THEN 'المنافسة كتواجه أصل المشكل ولكن النتيجة كتحتاج الوقت. تحديد الأثمنة يقدر يريح الناس بسرعة، ولكن يقدر يخلق الخصاص أو يكلف الدولة.'
        WHEN 'sme-jobs' THEN 'المقاولات تقدر تخلق فرص شغل مختلفة ودائمة، ولكن خاصها التمويل ومنافسة نزيهة. التوظيف فالقطاع العام مباشر ولكن محدود بميزانية الدولة.'
        WHEN 'youth-apprenticeships' THEN 'التدريب فالمقاولات يقدر يسهل على الشباب يلقاو أول خدمة. ولكن خاص التكوين يبقى مزيان وما يتحولش لخدمة رخيصة.'
        WHEN 'women-work' THEN 'هاد الخدمات كتنقص من العوائق اللي كتصعب الخدمة على النساء، ولكن كتحتاج التمويل والتنسيق بين الدولة والشركات والجماعات.'
        WHEN 'learning-accountability' THEN 'باش يتحسن المستوى، خاصنا معطيات صحيحة ومواكبة للأساتذة. وفنفس الوقت، كاينين مناطق ما زال خاصها مدارس وتجهيزات.'
        WHEN 'preschool-dropout' THEN 'التدخل بكري يقدر ينقص الفوارق من الأصل. ولكن حتى الجامعات فيها ضغط وخصها جودة وبلايص أكثر.'
        WHEN 'primary-care' THEN 'العلاج القريب كيحل بزاف ديال المشاكل بكري وكيخفف الضغط. ولكن الحالات الصعيبة كتبقى محتاجة مستشفيات مجهزة.'
        WHEN 'medicine-financing' THEN 'تمويل أكثر كينقص شحال كيخلصو الناس من جيبهم، ولكن خاص موارد دائمة وتدبير مزيان باش يبقى النظام واقف.'
        WHEN 'water-allocation' THEN 'هاد الاختيار كيحمي الما الضروري والمخزون، ولكن يقدر ينقص مداخيل الفلاحة والمناطق اللي عايشة من هاد الزراعات.'
        WHEN 'water-demand' THEN 'توفير الما غالبا أقل كلفة. ولكن التحلية ونقل الما يقدرو يجيبو ما إضافي للمدن والمناطق اللي فيها الخصاص.'
        WHEN 'universal-protection' THEN 'الحماية للجميع كتنقص من الناس اللي كيبقاو بلا تغطية وكتقوي التضامن. ولكن خاصها تمويل واضح وتطبيق بالتدريج.'
        WHEN 'public-transparency' THEN 'الوضوح كيسهل المراقبة وكيقلل تضارب المصالح. ولكن المساطر خاصها تبقى بسيطة باش ما تعطلش المشاريع.'
        WHEN 'regional-powers' THEN 'القرار اللي كيتاخد قريب من الناس يقدر يناسب الحاجيات المحلية. ولكن الفرق فالإمكانيات بين الجهات يقدر يزيد الفوارق إلا ما كانتش المواكبة.'
        WHEN 'connected-territories' THEN 'توزيع الاستثمار كيخفف الفوارق وكيخلي الناس ما يضطروش يهاجرو. والمشاريع الكبرى تقدر من جهتها تجيب نمو سريع وتخدم ناس بزاف فالمدن الاقتصادية.'
        WHEN 'equality-care' THEN 'المساواة فالحقوق والخدمات تقدر توسع الاختيارات والمشاركة. ولكن التطبيق كيحتاج نقاش مجتمعي ومؤسسات كتضمن الحقوق.'
        ELSE context_ar
    END
WHERE edition_id = 'c1000000-0000-4000-8000-000000000001';
